use serde_json::{json,Value};
use sqlx::{Postgres,QueryBuilder};
use super::resource::{invalid,validate,VM,Resource,issue,coerce_bool};
use crate::api::deps::ApiError;
use std::collections::BTreeMap;
pub type Params=BTreeMap<String,Vec<String>>;
pub fn query(raw:Option<String>)->Params {let mut p=Params::new();if let Some(raw)=raw{for pair in raw.split('&'){let(k,v)=pair.split_once('=').unwrap_or((pair,""));p.entry(decode(k)).or_default().push(decode(v));}}p}
fn decode(s:&str)->String{let mut bytes=Vec::new();let b=s.as_bytes();let mut i=0;while i<b.len(){if b[i]==b'%'&&i+2<b.len(){if let Ok(n)=u8::from_str_radix(&s[i+1..i+3],16){bytes.push(n);i+=3;continue;}}bytes.push(if b[i]==b'+'{b' '}else{b[i]});i+=1;}String::from_utf8_lossy(&bytes).into_owned()}
pub fn first<'a>(p:&'a Params,k:&str)->Option<&'a str>{p.get(k).and_then(|v|v.last()).map(String::as_str)}
pub fn boolean(p:&Params,k:&str)->Result<Option<bool>,ApiError>{first(p,k).map(|s|coerce_bool(&json!(s)).ok_or_else(||ApiError::validation(vec![issue(vec![json!("query"),json!(k)],"bool_parsing","Input should be a valid boolean, unable to interpret input",&json!(s))]))).transpose()}
pub fn bounded(p:&Params,key:&str,default:i64,min:i64,max:Option<i64>)->Result<i64,ApiError>{
 let Some(s)=first(p,key)else{return Ok(default)};
 let n=s.parse::<i64>().map_err(|_|ApiError::validation(vec![issue(vec![json!("query"),json!(key)],"int_parsing","Input should be a valid integer, unable to parse string as an integer",&json!(s))]))?;
 if n<min||max.is_some_and(|m|n>m){let high=n>=min;let bound=if high{max.unwrap()}else{min};let mut e=issue(vec![json!("query"),json!(key)],if high{"less_than_equal"}else{"greater_than_equal"},format!("Input should be {} than or equal to {bound}",if high{"less"}else{"greater"}),&json!(s));e["ctx"]=if high{json!({"le":bound})}else{json!({"ge":bound})};return Err(ApiError::validation(vec![e]));}Ok(n)
}
pub fn validate_query(p:&Params)->Result<(),ApiError>{
 let mut errors=Vec::new();
 for key in ["platform","status","environment","criticality","os_family","ip_role"]{if let Some(values)=p.get(key){for(i,s)in values.iter().enumerate(){
  let field=if key=="ip_role"{"role"}else{key};let r=Resource{table:"bulk",fields:if key=="ip_role"{"role"}else{VM.fields},..VM};
  if let Err(e)=validate(r,json!({field:s}),false){if let Some(Value::Array(es))=e.detail{for mut e in es{e["loc"]=json!(["query",key,i]);errors.push(e);}}}
 }}}
 for key in ["monitoring_enabled","pmp_enabled","shutdown_stale","decommission_overdue","missing_ip","duplicate_ip","all"]{if let Err(e)=boolean(p,key){errors.extend(e.detail.unwrap().as_array().unwrap().iter().cloned());}}
 for(key,values)in p{if key.ends_with("_op"){let s=values.last().unwrap();if !["eq","neq","contains"].contains(&s.as_str()){let mut e=issue(vec![json!("query"),json!(key)],"enum","Input should be 'eq', 'neq' or 'contains'",&json!(s));e["ctx"]=json!({"expected":"'eq', 'neq' or 'contains'"});errors.push(e);}}}
 for(key,valid,pattern)in[("health",vec!["below_50","below_75","complete"],"^(below_50|below_75|complete)$"),("dir",vec!["asc","desc"],"^(asc|desc)$"),("sort",vec!["name","updated_at","cluster","platform","status","environment","criticality","cpu_cores","memory_mb","owner","health"],"^(name|updated_at|cluster|platform|status|environment|criticality|cpu_cores|memory_mb|owner|health)$")]{if let Some(s)=first(p,key){if !valid.contains(&s){let mut e=issue(vec![json!("query"),json!(key)],"string_pattern_mismatch",format!("String should match pattern '{pattern}'"),&json!(s));e["ctx"]=json!({"pattern":pattern});errors.push(e);}}}
 if errors.is_empty(){Ok(())}else{Err(ApiError::validation(errors))}
}
pub fn apply(b:&mut QueryBuilder<Postgres>,p:&Params)->Result<(),ApiError>{
 for key in ["platform","status","environment","criticality","os_family","node","cluster"]{if let Some(values)=p.get(key).filter(|v|!v.is_empty()){for v in values {if ["platform","status","environment","criticality","os_family"].contains(&key){validate(VM,json!({key:v}),false)?;}}let op=first(p,&format!("{key}_op")).unwrap_or("eq");check_op(op)?;b.push(" AND (");b.push(format!("v.{key}::text "));if op=="neq"{b.push("NOT ");}b.push("IN (");let mut s=b.separated(",");for v in values{s.push_bind(v.clone());}s.push_unseparated(")");if op=="neq"{b.push(format!(" OR v.{key} IS NULL"));}b.push(")");}}
 for key in ["monitoring_enabled","pmp_enabled"]{if let Some(v)=boolean(p,key)?{let op=first(p,&format!("{key}_op")).unwrap_or("eq");check_op(op)?;b.push(format!(" AND v.{key} {} ",if op=="neq"{"<>"}else{"="})).push_bind(v);}}
 if let Some(q)=first(p,"q").filter(|s|!s.is_empty()){b.push(" AND (");for(i,key)in ["name","cluster","owner","fqdn","external_id","sr_id","os_distribution","os_version"].iter().enumerate(){if i>0{b.push(" OR ");}b.push(format!("lower(coalesce(v.{key},'')) LIKE ")).push_bind(format!("%{}%",q.trim().to_lowercase()));}b.push(" OR v.tags::text LIKE ").push_bind(format!("%{}%",q.trim()));for(table,col)in[("vm_networks","ip_address"),("vm_applications","app_name")]{b.push(format!(" OR EXISTS(SELECT 1 FROM {table} x WHERE x.vm_id=v.id AND lower(x.{col}) LIKE ")).push_bind(format!("%{}%",q.trim().to_lowercase())).push(")");}b.push(")");}
 for key in ["owner","tag","application"]{if let Some(values)=p.get(key).filter(|v|!v.is_empty()){let op=first(p,&format!("{key}_op")).unwrap_or(if key=="application"{"contains"}else{"eq"});check_op(op)?;b.push(" AND ");if op=="neq"{b.push("NOT ");}b.push("(");for(i,value)in values.iter().enumerate(){if i>0{b.push(" OR ");}match key{"owner"=>{b.push("(");for(j,col)in["owner","business_owner","technical_owner"].iter().enumerate(){if j>0{b.push(" OR ");}b.push(format!("lower(coalesce(v.{col},'')) = ")).push_bind(value.trim().to_lowercase());}b.push(")");},"tag"=>{b.push("v.tags @> ").push_bind(json!([value.trim()]));},_=>{b.push("EXISTS(SELECT 1 FROM vm_applications a WHERE a.vm_id=v.id AND lower(a.app_name) ");b.push(if op=="contains"{"LIKE "}else{"= "});b.push_bind(if op=="contains"{format!("%{}%",value.trim().to_lowercase())}else{value.trim().to_lowercase()}).push(")");}}}b.push(")");}}
 if let Some(roles)=p.get("ip_role").filter(|v|!v.is_empty()){b.push(" AND EXISTS(SELECT 1 FROM vm_networks n WHERE n.vm_id=v.id AND n.role::text IN (");let mut s=b.separated(",");for role in roles{if !["private","public","backup"].contains(&role.as_str()){return Err(invalid("Invalid ip_role"));}s.push_bind(role.clone());}s.push_unseparated("))");}
 if let Some(health)=first(p,"health"){let cond=match health{"below_50"=>"v.health_score<50","below_75"=>"v.health_score<75","complete"=>"v.health_score>=100",_=>return Err(invalid("Invalid health"))};b.push(format!(" AND {cond} AND NOT jsonb_path_exists(v.tags,'$[*] ? (@ like_regex \"^template$\" flag \"i\")')"));}
 for(key,expr)in[("shutdown_stale","v.status='powered_off' AND coalesce((SELECT max(changed_at) FROM audit_log WHERE vm_id=v.id AND field_name='status' AND new_value='powered_off'),v.created_at)<=now()-interval '90 days'"),("decommission_overdue","v.decommission_date IS NOT NULL AND v.decommission_date<=(now() AT TIME ZONE 'UTC')::date AND v.status<>'decommissioned'"),("missing_ip","NOT EXISTS(SELECT 1 FROM vm_networks WHERE vm_id=v.id)"),("duplicate_ip","v.status<>'decommissioned' AND EXISTS(SELECT 1 FROM vm_networks mine WHERE mine.vm_id=v.id AND EXISTS(SELECT 1 FROM vm_networks other JOIN vms ov ON ov.id=other.vm_id WHERE other.ip_address=mine.ip_address AND other.role=mine.role AND other.vm_id<>mine.vm_id AND ov.status<>'decommissioned' AND NOT jsonb_path_exists(ov.tags,'$[*] ? (@ like_regex \"^template$\" flag \"i\")')))" )]{if let Some(value)=boolean(p,key)?{b.push(" AND ");if !value{b.push("NOT ");}b.push(format!("({expr})"));}}
 Ok(())}
fn check_op(op:&str)->Result<(),ApiError>{if ["eq","neq","contains"].contains(&op){Ok(())}else{Err(invalid("Invalid filter operator"))}}
pub fn ordering(p:&Params)->Result<String,ApiError>{let dir=first(p,"dir").unwrap_or("asc");if !["asc","desc"].contains(&dir){return Err(invalid("Invalid sort direction"));}let key=first(p,"sort");let col=match key{None=>return Ok("v.updated_at DESC,v.name ASC".into()),Some("status")=>"CASE v.status WHEN 'running' THEN 0 WHEN 'powered_off' THEN 1 WHEN 'unknown' THEN 2 ELSE 3 END",Some("criticality")=>"CASE v.criticality WHEN 'critical' THEN 0 WHEN 'high' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END",Some("health")=>"v.health_score",Some(k)if["name","updated_at","cluster","platform","environment","cpu_cores","memory_mb","owner"].contains(&k)=>return Ok(format!("v.{k} {dir},v.name ASC")),_=>return Err(invalid("Invalid sort"))};Ok(format!("{col} {dir},v.name ASC"))}
#[cfg(test)]mod validation_tests{use super::*;
 #[test]fn repeated_enum_error_has_query_index(){let p=query(Some("status=running&status=stopped&platform=invalid".into()));let e=validate_query(&p).unwrap_err();let d=e.detail.unwrap();assert!(d.as_array().unwrap().iter().any(|e|e["loc"]==json!(["query","status",1])));assert!(d.as_array().unwrap().iter().any(|e|e["loc"]==json!(["query","platform",0])));}
 #[test]fn negative_limit_is_a_bound_error(){let p=query(Some("limit=-1".into()));let e=bounded(&p,"limit",50,1,Some(200)).unwrap_err();assert_eq!(e.detail.unwrap(),json!([{"type":"greater_than_equal","loc":["query","limit"],"msg":"Input should be greater than or equal to 1","input":"-1","ctx":{"ge":1}}]));}
}
